static void drm_test_cmdline_force_e_only ( struct kunit * test ) { const char * cmdline = "e" ; KUNIT_ASSERT_TRUE ( test , drm_mode_parse_command_line_for_connector ( cmdline , & no_connector , & mode ) ) ; KUNIT_EXPECT_FALSE ( test , mode . specified ) ; KUNIT_EXPECT_FALSE ( test , mode . refresh_specified ) ; KUNIT_EXPECT_FALSE ( test , mode . bpp_specified ) ; KUNIT_EXPECT_FALSE ( test , mode . rb ) ; KUNIT_EXPECT_FALSE ( test , mode . cvt ) ; KUNIT_EXPECT_FALSE ( test , mode . interlace ) ; KUNIT_EXPECT_FALSE ( test , mode . margins ) ; KUNIT_EXPECT_EQ ( test , mode . force , DRM_FORCE_ON ) ; } 